f2b5977d8e5e13b8c3f2e5643411ce2847bd7d2a798f7ee356406f09eafb06","argNames":["ctx","contract_id","id"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true},{"name":"native_employment_lifecycle_propose_v2","signature":"public.native_employment_lifecycle_propose_v2(jsonb,jsonb,uuid)","sha256":"e55dc4d1bc4bb434f0383eaec98c62b3e3684f0d1cd158d1fe1f4eea13192ab3","argNames":["ctx","body","key"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true},{"name":"native_employment_lifecycle_review_v2","signature":"public.native_employment_lifecycle_review_v2(jsonb,jsonb,uuid)","sha256":"c500c129a9a898d7fb1092412ee30bc6e652a8b2eef83f1a17e1da49e712dfa9","argNames":["ctx","body","key"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true},{"name":"native_employment_lifecycle_attempt_v2","signature":"public.native_employment_lifecycle_attempt_v2(jsonb,uuid,uuid)","sha256":"e5e2ded73c23a6fa6c819e78e7a8528b342f568b034e754da2706045c40e276b","argNames":["ctx","contract_id","key"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true},{"name":"native_employment_lifecycle_read_v2","signature":"public.native_employment_lifecycle_read_v2(jsonb,uuid)","sha256":"5619227331de0d310aee55fd724e7faee2256a4917e29cfd2c56fb8372b84914","argNames":["ctx","contract_id"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true},{"name":"native_employment_lifecycle_projection_v2","signature":"public.native_employment_lifecycle_projection_v2(jsonb,uuid)","sha256":"0c61b298a49cd6c7632bdb30ac30f229365e19cb8c475046979177c1c244f364","argNames":["ctx","contract_id"],"defaults":"","resultType":"jsonb","language":"plpgsql","returnsSet":false,"strict":false,"definer":true,"volatility":"v","config":["search_path=pg_catalog, public, pg_temp","TimeZone=UTC"],"runtime":true}]''::jsonb) LOOP
  SELECT * INTO p FROM pg_proc WHERE oid=to_regprocedure(x->>''signature'');
  IF p.oid IS NULL OR p.proowner<>current_user::regrole OR p.prokind<>''f'' OR p.prosecdef IS DISTINCT FROM (x->>''definer'')::boolean OR p.proisstrict IS DISTINCT FROM (x->>''strict'')::boolean OR p.proretset IS DISTINCT FROM (x->>''returnsSet'')::boolean
   OR p.prorettype<>(x->>''resultType'')::regtype OR p.provolatile<>x->>''volatility'' OR p.proparallel<>''u'' OR p.proleakproof OR p.prosupport<>0 OR p.procost<>100 OR p.prorows<>(CASE WHEN p.proretset THEN 1000 ELSE 0 END)
   OR p.proargmodes IS NOT NULL OR p.proallargtypes IS NOT NULL OR coalesce(to_jsonb(p.proargnames),''[]''::jsonb) IS DISTINCT FROM x->''argNames'' OR coalesce(pg_get_expr(p.proargdefaults,0),'''')<>x->>''defaults''
   OR coalesce(to_jsonb(p.proconfig),''[]''::jsonb) IS DISTINCT FROM x->''config'' OR (SELECT lanname FROM pg_language WHERE oid=p.prolang)<>x->>''language''
   OR encode(public.digest(replace(p.prosrc,E''\r\n'',E''\n''),''sha256''),''hex'')<>x->>''sha256''
   OR has_function_privilege(''municontrol_actions_runtime_app'',p.oid,''EXECUTE'') IS DISTINCT FROM (x->>''runtime'')::boolean
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a WHERE a.grantee<>p.proowner AND NOT((x->>''runtime'')::boolean AND a.grantee=''municontrol_actions_runtime_app''::regrole AND a.privilege_type=''EXECUTE'' AND NOT a.is_grantable))
  THEN RAISE EXCEPTION ''ADOPTION_INSTALL_FUNCTION_METADATA'' USING DETAIL=x->>''signature''; END IF;
 END LOOP; END $metadata$';
EXECUTE 'DO $tables$ DECLARE shapes jsonb:=(SELECT jsonb_object_agg(name,shape ORDER BY name) FROM (
 SELECT c.relname AS name,jsonb_build_object(''columns'',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 ''constraints'',(SELECT jsonb_agg(jsonb_build_array(k.conname,k.contype,pg_get_constraintdef(k.oid),k.convalidated,k.condeferrable,k.condeferred) ORDER BY k.conname COLLATE "C") FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>''n''),
 ''indexes'',(SELECT jsonb_agg(jsonb_build_array(ic.relname,pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready,i.indimmediate) ORDER BY ic.relname COLLATE "C") FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 ''triggers'',(SELECT jsonb_agg(jsonb_build_array(t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) ORDER BY t.tgname COLLATE "C") FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal),''rls'',c.relrowsecurity,''forceRls'',c.relforcerowsecurity,''kind'',c.relkind,''persistence'',c.relpersistence,''options'',c.reloptions,''replicaIdentity'',c.relreplident) AS shape
 FROM pg_class c WHERE c.oid IN(SELECT oid FROM pg_class WHERE relnamespace=''public''::regnamespace AND relname IN(''employment_adoption_proposal'',''employment_adoption_seal'',''employment_adoption_decision'',''employment_adoption_application''))) shapes);item jsonb;c pg_class; BEGIN
 FOR item IN SELECT value FROM jsonb_array_elements(''[{"name":"employment_adoption_proposal","sha256":"a286c75c611cd5426d0a0cc69213723bc5d1f1f65f0dda442581af732e415bd9"},{"name":"employment_adoption_seal","sha256":"a35224a95352def06f0b377db1d2c4723cd8ff362f067bd06337de983b9ce45c"},{"name":"employment_adoption_decision","sha256":"fa3291f45332de32bfcb47f94713948e7488b8834d509c1697d1efeac4338117"},{"name":"employment_adoption_application","sha256":"e58eaeed23e997f88caa161992695d88f0caacf728c5283e483c0e4ed261d608"}]''::jsonb) LOOP
  SELECT * INTO c FROM pg_class WHERE oid=to_regclass(''public.''||(item->>''name''));
  IF c.oid IS NULL OR c.relowner<>current_user::regrole OR encode(public.digest((shapes->(item->>''name''))::text,''sha256''),''hex'')<>item->>''sha256''
   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) a WHERE a.grantee<>c.relowner)
   OR EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attacl IS NOT NULL)
   OR EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid)
  THEN RAISE EXCEPTION ''ADOPTION_INSTALL_TABLE_METADATA'' USING DETAIL=item->>''name'';END IF;
 END LOOP; END $tables$';
