   OR EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault(''f'',p.proowner))) a WHERE a.grantee<>p.proowner AND NOT((x->>''runtime'')::boolean AND a.grantee=''municontrol_actions_runtime_app''::regrole AND a.privilege_type=''EXECUTE'' AND NOT a.is_grantable))
  THEN RAISE EXCEPTION ''ADOPTED_NOVELTY_WRITER_METADATA'' USING DETAIL=x->>''signature''; END IF;
 END LOOP; END $metadata$';
EXECUTE 'DO $objects$ DECLARE r oid:=to_regclass(''public.own_payroll_novelty_event'');BEGIN
 IF r IS NULL OR(SELECT count(*) FROM pg_class WHERE oid=r AND relowner=current_user::regrole AND relkind=''r'' AND relpersistence=''p'' AND relrowsecurity AND NOT relforcerowsecurity)<>1 OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(''r'',c.relowner))) a WHERE c.oid=r AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=r) OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=r AND(attisdropped OR attidentity<>'''' OR attgenerated<>'''' OR attacl IS NOT NULL)) THEN RAISE EXCEPTION ''SQL130_TABLE_SECURITY'';END IF;
 IF(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=r AND a.attnum>0) IS DISTINCT FROM ''[["id","uuid",true,"gen_random_uuid()"],["tenant_id","uuid",true,null],["source_binding_id","uuid",true,null],["batch_id","uuid",true,null],["revision","integer",true,null],["command","text",true,null],["status","text",true,null],["period_month","date",true,null],["payroll_type","text",true,null],["content_sha256","text",true,null],["actor_membership_id","uuid",true,null],["actor_person_id","uuid",true,null],["actor_email","text",true,null],["actor_session_id","uuid",true,null],["actor_session_version","integer",true,null],["release_sha","text",true,null],["request_key","uuid",true,null],["request_sha256","text",true,null],["body","jsonb",true,null],["snapshot","jsonb",true,null],["recorded_at","timestamp with time zone",true,"clock_timestamp()"]]''::jsonb THEN RAISE EXCEPTION ''SQL130_TABLE_SHAPE'';END IF;
 IF(SELECT count(*) FROM pg_constraint WHERE conrelid=r AND contype=''c'' AND convalidated AND NOT condeferrable)<>13 OR(SELECT count(*) FROM pg_constraint WHERE conrelid=r AND contype=''f'' AND convalidated AND NOT condeferrable)<>5 OR(SELECT count(*) FROM pg_index WHERE indrelid=r AND indisunique AND indisvalid AND indisready AND indislive)<>4 THEN RAISE EXCEPTION ''SQL130_CONSTRAINT_SHAPE'';END IF;
 IF(SELECT count(*) FROM pg_trigger WHERE(tgrelid=''public.payroll_novelty_row''::regclass AND tgname=''own_novelty_legacy_row'' AND NOT tgisinternal AND tgenabled=''O'' AND tgtype=7 AND tgfoid=''public.own_novelty_legacy_row_v1()''::regprocedure AND tgqual IS NULL AND tgnargs=0 AND tgargs=''''::bytea AND tgconstraint=0 AND tgattr=''''::int2vector))<>1 OR(SELECT count(*) FROM pg_trigger WHERE tgrelid=r AND NOT tgisinternal AND tgenabled=''O'' AND tgfoid=''public.own_novelty_immutable_v1()''::regprocedure AND tgtype IN(27,34) AND tgnargs=0 AND tgqual IS NULL)<>2 THEN RAISE EXCEPTION ''SQL130_TRIGGER_SHAPE'';END IF;
 IF(SELECT count(*) FROM pg_proc WHERE pronamespace=''public''::regnamespace AND proname LIKE ''own_novelty_%'')<>16 THEN RAISE EXCEPTION ''SQL130_NEW_OBJECTS_NOT_EMPTY'';END IF;END $objects$'; END $operator$;
